const headers = $input.first().json.headers || {};
const token   = headers['x-internal-token'] || headers['X-Internal-Token'];

if (!token || token !== $env.INTERNAL_WEBHOOK_SECRET) {
  throw new Error('UNAUTHORIZED_REQUEST: invalid or missing token');
}

return [{ json: $input.first().json }];

// ── Extract and normalise reply data from Gmail webhook payload ────
// Gmail push notifications arrive via Pub/Sub with base64-encoded data.
// This node handles both direct webhook payloads and Pub/Sub format.

const body = $input.first().json.body || $input.first().json;

// Handle Gmail Pub/Sub base64 payload
let gmailData = body;
if (body.message?.data) {
  try {
    const decoded = Buffer.from(body.message.data, 'base64').toString('utf-8');
    gmailData = JSON.parse(decoded);
  } catch(e) {
    // Not base64 encoded — use as-is
  }
}

// Extract core fields — handle both Gmail API format and simplified webhook
const threadId  = gmailData.threadId  || gmailData.thread_id  || body.threadId  || null;
const messageId = gmailData.messageId || gmailData.message_id || body.messageId || null;
const fromEmail = (gmailData.from || gmailData.sender || body.from || '').toLowerCase().trim();
const toEmail   = (gmailData.to   || body.to   || '').toLowerCase().trim();
const subject   = gmailData.subject || body.subject || '';
const bodyText  = gmailData.bodyText || gmailData.body_text || gmailData.snippet || body.body || '';
const receivedAt = gmailData.receivedAt || body.received_at || new Date().toISOString();

if (!threadId && !fromEmail) {
  throw new Error('REPLY_PARSE_FAILED: cannot identify thread or sender');
}

// Strip quoted text — keep only the new reply content
const cleanBody = bodyText
  .split(/\n>|\nOn .+ wrote:|\n--+\s*Original Message/i)[0]
  .trim()
  .slice(0, 5000);  // cap to prevent oversized payloads

return [{
  json: {
    thread_id:   threadId,
    message_id:  messageId,
    from_email:  fromEmail,
    to_email:    toEmail,
    subject,
    body_text:   cleanBody,
    raw_body:    bodyText.slice(0, 2000),
    received_at: receivedAt
  }
}];

// ── Merge thread-match and email-match results ─────────────────────
// Use thread match if available; fall back to email match.
// If neither found, throw — we can't process an unmatched reply.

const replyData  = $items('Extract Reply Data')[0].json;
const threadMatch = $items('Match Lead by Thread ID');
const emailMatch  = $items('Fallback: Match by Email');

const match =
  (threadMatch.length > 0 && threadMatch[0].json.lead_id ? threadMatch[0].json : null) ||
  (emailMatch.length  > 0 && emailMatch[0].json.lead_id  ? emailMatch[0].json  : null);

if (!match || !match.lead_id) {
  throw new Error(`UNMATCHED_REPLY: no lead found for thread ${replyData.thread_id} / email ${replyData.from_email}`);
}

// Parse brief if string
const parseCol = (v) => {
  if (!v) return {};
  if (typeof v === 'object') return v;
  try { return JSON.parse(v); } catch(e) { return {}; }
};

return [{
  json: {
    ...replyData,
    ...match,
    brief:      parseCol(match.brief),
    match_type: threadMatch.length > 0 && threadMatch[0].json.lead_id ? 'thread' : 'email'
  }
}];

// ── Build conversation context for classification ──────────────────
// Combines Redis memory summary (if cached) with recent conversation
// turns. Caps total context to prevent token explosion.

const merged     = $items('Merge Lead Match')[0].json;
const history    = $items('Load Conversation History').map(i => i.json);
const memoryCached = $items('Check Memory Summary')[0].json.value || null;

let memoryParsed = null;
if (memoryCached) {
  try { memoryParsed = JSON.parse(memoryCached); } catch(e) {}
}

// Format conversation turns for prompt
const safe = (t, max = 500) => String(t || '').slice(0, max);

const historyLines = history.map(h =>
  `[${h.direction === 'outbound' ? 'US' : 'LEAD'} @ ${(h.sent_at || '').slice(0,10)}]: ${safe(h.body_text, 300)}`
).join('\n');

// Append the new reply as the latest turn
const fullContext =
  (memoryParsed?.summary ? `PRIOR SUMMARY: ${memoryParsed.summary}\n\n` : '') +
  (historyLines ? `CONVERSATION HISTORY:\n${historyLines}\n\n` : '') +
  `LATEST REPLY FROM LEAD:\n${safe(merged.body_text, 1000)}`;

return [{
  json: {
    ...merged,
    conversation_history: history,
    conversation_context: fullContext.slice(0, 4000),  // hard cap
    has_memory_cache:     !!memoryParsed,
    memory_summary:       memoryParsed?.summary || null,
    turn_count:           history.length
  }
}];

