// ── Parse intent classification response ──────────────────────────
const raw = $input.first().json?.choices?.[0]?.message?.content
         || $input.first().json?.message?.content || '';

let intent = {};
try {
  const start = raw.indexOf('{');
  const end   = raw.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('no JSON found');
  intent = JSON.parse(raw.slice(start, end + 1));
} catch(e) {
  // Fallback classification on parse failure
  intent = {
    intent:           'NEUTRAL',
    sentiment:        'NEUTRAL',
    confidence:       0.3,
    confidence_reason: 'parse failed — manual review needed',
    key_signals:      [],
    objection_type:   null,
    referral_name:    null,
    urgency:          'LOW',
    summary:          raw.slice(0, 200)
  };
}

const ctx = $items('Build Conversation Context')[0].json;

return [{
  json: {
    ...ctx,
    intent:           intent.intent           || 'NEUTRAL',
    sentiment:        intent.sentiment         || 'NEUTRAL',
    intent_confidence: parseFloat(intent.confidence) || 0.5,
    confidence_reason: intent.confidence_reason || '',
    key_signals:      intent.key_signals       || [],
    objection_type:   intent.objection_type    || null,
    referral_name:    intent.referral_name     || null,
    urgency:          intent.urgency           || 'LOW',
    reply_summary:    intent.summary           || '',
    classified_at:    new Date().toISOString()
  }
}];

// ── Update Redis memory summary ────────────────────────────────────
// Builds a rolling summary of the conversation state.
// Stored at memory:lead:{lead_id} with 30-day TTL.
// This is the agent's working memory — avoids re-reading full history.

const d = $input.first().json;

const existing = d.memory_summary || '';

const newEntry =
  `[${new Date().toISOString().slice(0,10)}] ` +
  `Step ${d.step_number} reply — Intent: ${d.intent} (${Math.round(d.intent_confidence * 100)}%) ` +
  `| Sentiment: ${d.sentiment} | Urgency: ${d.urgency}\n` +
  `Summary: ${d.reply_summary}`;

// Keep last 3 entries in memory (rolling window)
const entries = [
  ...existing.split('\n---\n').filter(Boolean),
  newEntry
].slice(-3);

const updatedSummary = entries.join('\n---\n');

const memoryPayload = JSON.stringify({
  lead_id:        d.lead_id,
  summary:        updatedSummary,
  last_intent:    d.intent,
  last_sentiment: d.sentiment,
  turn_count:     d.turn_count + 1,
  updated_at:     new Date().toISOString()
});

return [{
  json: {
    ...d,
    updated_memory:  updatedSummary,
    memory_payload:  memoryPayload,
    memory_key:      `memory:lead:${d.lead_id}`
  }
}];

