// ── Parse Agent Planner decision ──────────────────────────────────
const raw = $input.first().json?.choices?.[0]?.message?.content
         || $input.first().json?.message?.content || '';

let decision = {};
try {
  const start = raw.indexOf('{');
  const end   = raw.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('no JSON');
  decision = JSON.parse(raw.slice(start, end + 1));
} catch(e) {
  // Always escalate on parse failure — never silently drop a reply
  decision = {
    action:            'escalate_to_human',
    reason:            'planner parse failed — needs manual review',
    confidence:        0.0,
    urgency:           'HIGH',
    reply_draft:       null,
    escalation_reason: `Parse error: ${e.message}`
  };
}

// Force escalation on low confidence
const confidence = parseFloat(decision.confidence) || 0;
if (confidence < 0.6 && decision.action !== 'escalate_to_human') {
  decision.escalation_reason = `Low planner confidence: ${confidence}`;
  decision.action = 'escalate_to_human';
}

const ctx = $items('Build Conversation Context')[0].json;

return [{
  json: {
    ...ctx,
    action:               decision.action,
    action_reason:        decision.reason,
    planner_confidence:   confidence,
    planner_urgency:      decision.urgency           || 'LOW',
    reply_draft:          decision.reply_draft        || null,
    followup_delay_days:  decision.followup_delay_days || null,
    meeting_context:      decision.meeting_context    || null,
    escalation_reason:    decision.escalation_reason  || null,
    decided_at:           new Date().toISOString(),
    execution_id:         $execution.id
  }
}];

// ── Guardrail check on AI-drafted reply ───────────────────────────
// Same guardrail logic as WF-04 but lighter — this is a reply,
// not a cold email, so rules are slightly relaxed.

const { reply_draft, first_name, company } = $input.first().json;

if (!reply_draft || reply_draft.trim().length < 10) {
  throw new Error('GUARDRAIL_FAIL: reply_draft is empty or too short');
}

const body = reply_draft.toLowerCase();
const violations = [];

// Placeholder leakage
if (/\[.*?\]|\{.*?\}|\bUNKNOWN\b/i.test(reply_draft)) {
  violations.push('placeholder_leakage');
}

// Legal risk
if (/guaranteed roi|we promise|100% results/i.test(body)) {
  violations.push('legal_risk');
}

// Too long for a reply (>200 words)
const wordCount = reply_draft.trim().split(/\s+/).length;
if (wordCount > 200) {
  violations.push(`reply_too_long: ${wordCount} words`);
}

// Competitor mentions
const competitors = ($env.COMPETITOR_NAMES || '').split(',').filter(Boolean);
if (competitors.some(c => body.includes(c.toLowerCase().trim()))) {
  violations.push('competitor_mention');
}

const passed = violations.length === 0;

return [{
  json: {
    ...$input.first().json,
    guardrail_passed:     passed,
    guardrail_violations: violations,
    reply_word_count:     wordCount
  }
}];

