const err = $input.first().error || {};
const msg = err.message || 'Unknown error in WF-06';

const isAuth      = msg.includes('UNAUTHORIZED_REQUEST');
const isUnmatched = msg.includes('UNMATCHED_REPLY');
const isParseFail = msg.includes('REPLY_PARSE_FAILED');

return [{
  json: {
    status:       isAuth ? 'unauthorized' : isUnmatched ? 'unmatched' : isParseFail ? 'parse_error' : 'error',
    message:      msg,
    workflow:     'WF-06',
    timestamp:    new Date().toISOString(),
    execution_id: $execution.id
  }
}];
